create table if not exists iotf.private_platform_readiness (id uuid primary key default gen_random_uuid(),instrument_id uuid not null unique references iotf.instruments(id) on delete cascade,operative_status text not null default 'NON_OPERATIVE_DRAFT',swift_transmission_status text not null default 'NOT_TRANSMITTED',issuer_acknowledgement_status text not null default 'NOT_RECEIVED',transfer_consent_status text not null default 'REQUIRED_NOT_RECEIVED',platform_bank_acceptance_status text not null default 'NOT_RECEIVED',custody_settlement_status text not null default 'NOT_ESTABLISHED',platform_submission_status text not null default 'PREPARATORY_ONLY',deployable_cash numeric(20,2) not null default 0,realized_liquidity numeric(20,2) not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table iotf.private_platform_readiness enable row level security; revoke all on iotf.private_platform_readiness from public,anon,authenticated; grant select,insert,update,delete on iotf.private_platform_readiness to service_role;
create table if not exists iotf.private_platform_requirements(id uuid primary key default gen_random_uuid(),instrument_id uuid not null references iotf.instruments(id) on delete cascade,requirement_code text not null,requirement_class text not null,requirement_text text not null,status text not null default 'OUTSTANDING',blocking boolean not null default true,evidence_reference text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(instrument_id,requirement_code)); alter table iotf.private_platform_requirements enable row level security; revoke all on iotf.private_platform_requirements from public,anon,authenticated; grant select,insert,update,delete on iotf.private_platform_requirements to service_role;
create or replace view iotf.private_platform_readiness_matrix with(security_invoker=true) as select i.instrument_code,i.external_reference,i.face_currency,i.face_amount,i.recognition_status,i.evidence_status,p.operative_status,p.swift_transmission_status,p.issuer_acknowledgement_status,p.transfer_consent_status,p.platform_bank_acceptance_status,p.custody_settlement_status,p.platform_submission_status,p.deployable_cash,p.realized_liquidity,count(r.id) requirements,count(r.id) filter(where r.blocking and r.status not in ('VERIFIED','WAIVED_NOT_APPLICABLE')) unresolved_blockers from iotf.instruments i join iotf.private_platform_readiness p on p.instrument_id=i.id left join iotf.private_platform_requirements r on r.instrument_id=i.id group by i.id,p.id; revoke all on iotf.private_platform_readiness_matrix from public,anon,authenticated; grant select on iotf.private_platform_readiness_matrix to service_role;
