insert into iotf.instruments(instrument_code,instrument_type,message_type,external_reference,uetr,face_currency,face_amount,tenor_days,stated_purpose,applicant_name,beneficiary_name,beneficiary_bank_name,issuing_bank_name,governing_law,issued_at,recognition_status,evidence_status,deployable_cash,realized_liquidity,provenance) select 'SE-IOTF-SBLC-20260820-0002-11','SBLC','MT760-DRAFT','SBLC-20260820-0002-11','a045dd1f-7d3a-48e3-a276-5dab24c3a212'::uuid,'USD',153000000,365,'GOODS PURCHASE','BLOCKOAK EQUITY LTD','SOURCEENERGY FOUNDATION','TRUIST BANK','UBS SWITZERLAND AG','ENGLISH LAW','2026-08-20'::timestamptz,'CONDITIONAL','PENDING',0,0,jsonb_build_object('document_status','NON_OPERATIVE_DRAFT','issuer_acknowledgement','NOT_RECEIVED','swift_transmission','NOT_TRANSMITTED','transferability','whole or part only with prior written issuer consent','expiry_date','2027-08-20','sha256','ad3e36f8c33fb2c9c36711b21185b52bc54f2cd8a4224c5a72ca5edb9cfe2827') where not exists(select 1 from iotf.instruments where external_reference='SBLC-20260820-0002-11');
insert into iotf.private_platform_readiness(instrument_id,operative_status,swift_transmission_status,issuer_acknowledgement_status,transfer_consent_status,platform_bank_acceptance_status,custody_settlement_status,platform_submission_status,metadata) select id,'NON_OPERATIVE_DRAFT','NOT_TRANSMITTED','NOT_RECEIVED','REQUIRED_NOT_RECEIVED','NOT_RECEIVED','NOT_ESTABLISHED','G4_BLOCKED',jsonb_build_object('allowed_current_use',jsonb_build_array('platform pre-screening','intake preparation','compliance review','structure design','term negotiation'),'prohibited_representation','Do not represent as operative, authenticated, transmitted, deployable cash, or realized liquidity') from iotf.instruments where external_reference='SBLC-20260820-0002-11' on conflict(instrument_id) do update set operative_status=excluded.operative_status,swift_transmission_status=excluded.swift_transmission_status,issuer_acknowledgement_status=excluded.issuer_acknowledgement_status,transfer_consent_status=excluded.transfer_consent_status,platform_submission_status='G4_BLOCKED',deployable_cash=0,realized_liquidity=0,metadata=excluded.metadata,updated_at=now();
insert into iotf.governance_gates(instrument_id,allocation_id,gate_code,gate_status,decision_reference,decision_metadata) select i.id,null,g.code,'PENDING','SBLC-0002-INITIAL-CONTROL',jsonb_build_object('document_status','NON_OPERATIVE_DRAFT') from iotf.instruments i cross join (values ('G1_EVIDENCE'),('G2_ELIGIBILITY'),('G3_COMMERCIAL'),('G4_BANKING_LEGAL'),('G5_SETTLEMENT')) g(code) where i.external_reference='SBLC-20260820-0002-11' and not exists(select 1 from iotf.governance_gates e where e.instrument_id=i.id and e.allocation_id is null and e.gate_code=g.code);
insert into iotf.private_platform_requirements(instrument_id,requirement_code,requirement_class,requirement_text,metadata) select i.id,x.code,x.class,x.req,x.meta from iotf.instruments i cross join (values ('PP-ISSUER-AUTH','ISSUER_AUTHENTICATION','Independently verified execution/authentication and acknowledgement from named issuing bank.',jsonb_build_object('current','not received')),('PP-SWIFT-CONFIRM','SWIFT','Bank-to-bank confirmation of authenticated operative transmission where required.',jsonb_build_object('current','composed MT760 not transmitted')),('PP-TRANSFER-CONSENT','TRANSFER_CONSENT','Prior written issuing-bank consent for any whole or partial transfer structure requiring consent.',jsonb_build_object('current','required not received')),('PP-PLATFORM-BANK','PLATFORM_BANK','Written transaction-specific acceptance from platform receiving/custodian bank.',jsonb_build_object('current','not received')),('PP-LEGAL','LEGAL','Transaction-specific legal review of proposed transfer, collateral assignment, discounting or monetization.',jsonb_build_object('current','not received')),('PP-CUSTODY-SETTLEMENT','CUSTODY_SETTLEMENT','Verified custody, control, settlement and proceeds-flow mechanics.',jsonb_build_object('current','not established'))) x(code,class,req,meta) where i.external_reference='SBLC-20260820-0002-11' on conflict(instrument_id,requirement_code) do nothing;
